-- Sprint 6 focused Level 1 corrections. Migrations 033-034 remain immutable.
begin;

alter table public.s6_run_state add column if not exists feedback_text_keys text[] not null default '{}';
alter table public.s6_run_state add column if not exists feedback_audio_key text;
alter table public.s6_run_state add column if not exists cinematic_stage int not null default 0;
alter table public.s6_run_state add column if not exists stage_started_at timestamptz;

create table public.s6_action_receipts(
 run_id uuid references public.game_runs(run_id),player_id uuid references public.s1_room_players(player_id),
 request_id uuid,action_key text,payload jsonb not null,result jsonb,created_at timestamptz not null default now(),
 primary key(run_id,player_id,request_id)
);
create table public.s6_allocation_attempts(
 attempt_id bigint generated always as identity primary key,run_id uuid references public.game_runs(run_id),round_no int,
 player_id uuid references public.s1_room_players(player_id),role_key text,request_id uuid,submitted_at timestamptz not null default now(),
 unique(run_id,player_id,request_id)
);
create table public.s6_station_tasks(
 run_id uuid references public.game_runs(run_id),role_key text,player_id uuid references public.s1_room_players(player_id),
 task_key text,completed_at timestamptz not null default now(),primary key(run_id,role_key)
);
alter table public.s6_action_receipts enable row level security;
alter table public.s6_allocation_attempts enable row level security;
alter table public.s6_station_tasks enable row level security;

update public.s3_item_catalog set name_text_key='item.golden_key' where item_key='golden_key';
update public.s3_group_items set label_text_key='item.golden_key' where item_key='golden_key';

create function public.s6_open_discussion(p_run uuid,p_phase text,p_step text,p_seconds int,p_topic text)returns uuid language plpgsql security definer set search_path=public as $$
declare sid uuid;vr int;
begin update public.discussion_sessions set status='resolved',ended_at=now(),phase_deadline=null,outcome=jsonb_build_object('type','superseded_by_sprint6_transition')where run_id=p_run and status in('discussion','voting','waiting_for_missing_player');select coalesce(max(vote_round),0)+1 into vr from public.discussion_sessions where run_id=p_run;insert into public.discussion_sessions(run_id,scene_id,phase_key,step_key,round_no,vote_round,topic,status,phase_deadline,show_initial_choices,allow_free_text,require_final_vote,vote_options,tie_policy,discussion_time_limit_sec,vote_time_limit_sec,silent_texting_mode)values(p_run,'sprint6',p_phase,p_step,vr,vr,p_topic,'discussion',now()+make_interval(secs=>p_seconds),false,true,false,'[]','REPEAT_UNTIL_MAJORITY',p_seconds,60,true)returning discussion_session_id into sid;return sid;end$$;
revoke execute on function public.s6_open_discussion(uuid,text,text,int,text)from public,anon,authenticated;

create function public.s6_assert_identity(p_state public.s6_run_state,p_phase text,p_step int,p_round int)returns void language plpgsql immutable as $$begin if p_state.phase_key<>p_phase or p_state.act9_step<>p_step or p_state.round_no<>p_round then raise exception'Stale Sprint 6 interaction identity.';end if;end$$;
revoke execute on function public.s6_assert_identity(public.s6_run_state,text,int,int)from public,anon,authenticated;

create or replace function public.s6_initialize(p_room_code text,p_teacher_token text)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));g public.game_runs%rowtype;sid uuid;begin perform public.s1_assert_teacher(room,p_teacher_token);g:=public.s2_get_active_run(room);if not exists(select 1 from public.s5_run_state where run_id=g.run_id and phase_key='complete')then raise exception'Sprint 6 requires verified ACT 6-8 completion.';end if;insert into public.s6_run_state(run_id)values(g.run_id);perform public.s6_deliver_clues(g.run_id,9);sid:=public.s6_open_discussion(g.run_id,'act9_discussion','step_1',180,'act09.004');perform public.s6_set_scene(g.run_id,'act9_great_hall','act9_discussion','step_1','CINEMATIC_MESSAGE','act09.004');perform public.s2_log_event(g.run_id,room,sid,'s6_initialized',null,jsonb_build_object('behavior_scoring',false));return jsonb_build_object('ok',true,'run_id',g.run_id,'discussion_session_id',sid);end$$;

create function public.s6_send_message_guarded(p_room_code text,p_session_token text,p_expected_discussion_session_id uuid,p_client_request_id uuid,p_message_text text)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;d public.discussion_sessions%rowtype;t text:=trim(coalesce(p_message_text,''));prior public.s6_action_receipts%rowtype;mid bigint;begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'message'or prior.payload<>jsonb_build_object('session',p_expected_discussion_session_id,'text',t)then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into d from public.discussion_sessions where discussion_session_id=p_expected_discussion_session_id and run_id=g.run_id for update;if not found or d.status<>'discussion'or d.phase_deadline<=now()then raise exception'Stale or closed Sprint 6 discussion.';end if;if t=''or char_length(t)>1000 then raise exception'Message must contain 1-1000 characters.';end if;insert into public.dialogue_messages(run_id,discussion_session_id,scene_id,phase_key,step_key,player_id,message_text)values(g.run_id,d.discussion_session_id,d.scene_id,d.phase_key,d.step_key,p.player_id,t)returning message_id into mid;insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'message',jsonb_build_object('session',p_expected_discussion_session_id,'text',t),jsonb_build_object('ok',true,'message_id',mid),now());return jsonb_build_object('ok',true,'message_id',mid);end$$;

create function public.s6_close_discussion_guarded(p_room_code text,p_session_token text,p_expected_phase text,p_expected_step int,p_expected_round int,p_expected_discussion_session_id uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;d public.discussion_sessions%rowtype;nextphase text;begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);select*into d from public.discussion_sessions where discussion_session_id=p_expected_discussion_session_id and run_id=g.run_id for update;if not found or d.status<>'discussion'or d.phase_key<>p_expected_phase then raise exception'Stale Sprint 6 discussion identity.';end if;if d.phase_deadline>now()and(select run_mode from public.game_runs where run_id=g.run_id)<>'audit'then raise exception'Discussion timer is still active.';end if;update public.discussion_sessions set status='resolved',ended_at=now(),phase_deadline=null,outcome=jsonb_build_object('type','discussion_complete')where discussion_session_id=d.discussion_session_id;nextphase:=case p_expected_phase when'act9_discussion'then'act9_console'when'act10_discussion'then'act10_final_vote'when'act11_discussion'then'act11_allocation'else null end;if nextphase is null then raise exception'Invalid Sprint 6 discussion transition.';end if;update public.s6_run_state set phase_key=nextphase,feedback_text_keys='{}',feedback_audio_key=null,updated_at=now()where run_id=g.run_id;return jsonb_build_object('ok',true,'phase_key',nextphase);end$$;

create function public.s6_submit_group_choice_guarded(p_room_code text,p_session_token text,p_client_request_id uuid,p_choice_id text,p_expected_phase text,p_expected_step int,p_expected_round int)returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;prior public.s6_action_receipts%rowtype;n int;d int;winner text;correct boolean;keys text[];sid uuid;result jsonb;
begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'group_choice'or prior.payload<>jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round,'choice',p_choice_id)then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);if s.phase_key not in('act9_console','act10_final_vote')then raise exception'No Sprint 6 group choice is open.';end if;if s.phase_key='act10_final_vote'and p_choice_id not in('take','leave')then raise exception'Invalid ACT 10 choice.';end if;if s.phase_key='act9_console'and not(case when s.act9_step in(1,3)then p_choice_id in('red','blue','black')when s.act9_step=2 then p_choice_id in('enter_red','do_not_enter')when s.act9_step=4 then p_choice_id in('enter_blue','stay')else false end)then raise exception'Invalid Great Hall choice for current step.';end if;insert into public.s6_choices values(g.run_id,s.phase_key,s.round_no,p.player_id,p_choice_id,p_client_request_id,null,null,now());select count(*),count(distinct choice_id)into n,d from public.s6_choices where run_id=g.run_id and phase_key=s.phase_key and round_no=s.round_no;result:=jsonb_build_object('ok',true,'submitted',n);if n=3 then
 if d=3 then sid:=public.s6_open_discussion(g.run_id,'act9_discussion','step_'||s.act9_step,180,'act09.009');update public.s6_run_state set phase_key='act9_discussion',round_no=round_no+1,feedback_text_keys=array['act09.009'],updated_at=now()where run_id=g.run_id;result:=jsonb_build_object('ok',true,'no_consensus',true,'action_executed',false,'discussion_session_id',sid);
 else select choice_id into winner from public.s6_choices where run_id=g.run_id and phase_key=s.phase_key and round_no=s.round_no group by choice_id order by count(*)desc,choice_id limit 1;
  if s.phase_key='act10_final_vote'then update public.s6_run_state set gold_key=winner='take',alarm_active=winner='take',station_c_bypassed=winner='take',danger_arrives_sooner=winner='take',phase_key='act10_result',feedback_text_keys=case when winner='take'then array['act10.008']else array['act10.009']end,feedback_audio_key=case when winner='take'then'audio.old_alarm_bell'end,updated_at=now()where run_id=g.run_id;if winner='take'then insert into public.s3_group_items(run_id,item_key,label_text_key)values(g.run_id,'golden_key','item.golden_key')on conflict do nothing;end if;result:=jsonb_build_object('ok',true,'resolved',true,'choice_id',winner);
  else correct:=case s.act9_step when 1 then winner='red'when 2 then winner='do_not_enter'when 3 then winner='blue'else winner='enter_blue'end;
   if s.act9_step=4 and winner='stay'then update public.s6_run_state set round_no=round_no+1,feedback_text_keys=array['act09.021'],updated_at=now()where run_id=g.run_id;result:=jsonb_build_object('ok',true,'stay',true,'penalty',false,'action_executed',false);
   elsif not correct then keys:=case s.act9_step when 1 then array['act09.022']when 2 then array['act09.023','act09.024','act09.006']when 3 then array['act09.007']else array['act09.023','act09.024']end;sid:=public.s6_open_discussion(g.run_id,'act9_discussion','step_1',60,keys[1]);update public.s6_run_state set phase_key='act9_discussion',act9_step=1,red_activated=false,blue_activated=false,round_no=round_no+1,feedback_text_keys=keys,feedback_audio_key='audio.snake_hiss_short',updated_at=now()where run_id=g.run_id;perform public.s2_log_event(g.run_id,room,sid,'escape_penalty_event',null,jsonb_build_object('penalty_key','great_hall_wrong_door','resolution_source','group_majority','choice_id',winner,'behavior_scoring',false));result:=jsonb_build_object('ok',true,'soft_failure',true,'penalty',true,'discussion_session_id',sid);
   elsif s.act9_step<4 then keys:=case s.act9_step when 1 then array['act09.014']when 2 then array['act09.017','act09.018']else array['act09.019']end;update public.s6_run_state set act9_step=act9_step+1,red_activated=true,blue_activated=s.act9_step>=3,round_no=round_no+1,feedback_text_keys=keys,updated_at=now()where run_id=g.run_id;result:=jsonb_build_object('ok',true,'resolved',true,'choice_id',winner);
   else update public.s6_run_state set act_no=10,phase_key='act10_private',round_no=1,feedback_text_keys=array['act09.026','act09.027'],updated_at=now()where run_id=g.run_id;perform public.s6_deliver_clues(g.run_id,10);result:=jsonb_build_object('ok',true,'resolved',true,'choice_id',winner);end if;end if;end if;end if;
 insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'group_choice',jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round,'choice',p_choice_id),result,now());return result;end$$;

create function public.s6_submit_private_choice_guarded(p_room_code text,p_session_token text,p_client_request_id uuid,p_choice_id text,p_expected_phase text,p_expected_step int,p_expected_round int)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;prior public.s6_action_receipts%rowtype;n int;role text;result jsonb;sid uuid;payload jsonb:=jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round,'choice',p_choice_id);begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'private_choice'or prior.payload<>payload then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);role:=(select role_key from public.s6_allocations where run_id=g.run_id and player_id=p.player_id);if s.phase_key='act10_private'and p_choice_id not in('take','leave')then raise exception'Invalid ACT 10 private choice.';elsif s.phase_key='act12_pressure'and((role=s.mechanism_failure_station and p_choice_id not in('one','two','three','four'))or(role<>s.mechanism_failure_station and p_choice_id not in('hold','encourage','watch','prepare')))then raise exception'Invalid pressure choice for role context.';elsif s.phase_key not in('act10_private','act12_pressure')then raise exception'No private Sprint 6 choice is open.';end if;insert into public.s6_choices values(g.run_id,s.phase_key,s.round_no,p.player_id,p_choice_id,p_client_request_id,round(extract(epoch from(now()-s.updated_at))*1000)::int,role,now());select count(*)into n from public.s6_choices where run_id=g.run_id and phase_key=s.phase_key and round_no=s.round_no;result:=jsonb_build_object('ok',true,'submitted',n);if n=3 and s.phase_key='act10_private'then sid:=public.s6_open_discussion(g.run_id,'act10_discussion','reveal',300,'act10.004');update public.s6_run_state set phase_key='act10_discussion',round_no=1,updated_at=now()where run_id=g.run_id;result:=result||jsonb_build_object('discussion_session_id',sid);elsif n=3 then update public.s6_run_state set phase_key='act12_cinematic',cinematic_stage=1,stage_started_at=now(),failure_resolution='cinematic_auto_resolution_pending',feedback_text_keys=array['act12.016'],feedback_audio_key='audio.wet_scraping',updated_at=now()where run_id=g.run_id;end if;insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'private_choice',payload,result,now());return result;end$$;

create function public.s6_advance_guarded(p_room_code text,p_session_token text,p_client_request_id uuid,p_expected_phase text,p_expected_step int,p_expected_round int)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;prior public.s6_action_receipts%rowtype;sid uuid;result jsonb;payload jsonb:=jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round);begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'advance'or prior.payload<>payload then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);if s.phase_key='act10_result'then sid:=public.s6_open_discussion(g.run_id,'act11_discussion','allocation',case when s.gold_key then 45 else 90 end,'act11.001');update public.s6_run_state set act_no=11,phase_key='act11_discussion',round_no=1,feedback_text_keys=array['act11.001','act11.002','act11.003','act11.004'],feedback_audio_key=null,updated_at=now()where run_id=g.run_id;result:=jsonb_build_object('ok',true,'discussion_session_id',sid);elsif s.phase_key='act13_escape'and s.escape_success then update public.s6_run_state set phase_key='act13_boundary',act14_boundary_reached=true,updated_at=now()where run_id=g.run_id;result:=jsonb_build_object('ok',true,'act14_boundary_reached',true);else raise exception'No Sprint 6 transition is available.';end if;insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'advance',payload,result,now());return result;end$$;

create function public.s6_submit_allocation_guarded(p_room_code text,p_session_token text,p_client_request_id uuid,p_role_key text,p_expected_phase text,p_expected_step int,p_expected_round int)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;prior public.s6_action_receipts%rowtype;n int;dn int;c_owner text;valid boolean;result jsonb;payload jsonb:=jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round,'role',p_role_key);begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'allocation'or prior.payload<>payload then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);if s.phase_key<>'act11_allocation'then raise exception'Allocation is not open.';end if;if(s.gold_key and p_role_key not in('A','B','WATCHER'))or(not s.gold_key and p_role_key not in('A','B','C'))then raise exception'Invalid role for Golden Key branch.';end if;if exists(select 1 from public.s6_allocations where run_id=g.run_id and player_id=p.player_id)then raise exception'Allocation choice already locked for this round.';end if;insert into public.s6_allocation_attempts(run_id,round_no,player_id,role_key,request_id)values(g.run_id,s.round_no,p.player_id,p_role_key,p_client_request_id);insert into public.s6_allocations values(g.run_id,p.player_id,p_role_key,p_client_request_id,now());select count(*),count(distinct role_key)into n,dn from public.s6_allocations where run_id=g.run_id;result:=jsonb_build_object('ok',true,'submitted',n);if n=3 then select rp.role_slot into c_owner from public.s6_allocations a join public.s1_room_players rp using(player_id)where a.run_id=g.run_id and a.role_key='C';valid:=dn=3 and((s.gold_key and not exists(select 1 from public.s6_allocations where run_id=g.run_id and role_key not in('A','B','WATCHER')))or(not s.gold_key and not exists(select 1 from public.s6_allocations where run_id=g.run_id and role_key not in('A','B','C'))and c_owner='GAL-C'));if not valid then delete from public.s6_allocations where run_id=g.run_id;update public.s6_run_state set round_no=round_no+1,feedback_text_keys=case when c_owner is not null and c_owner<>'GAL-C'then array['act11.010']else array['act11.018']end,updated_at=now()where run_id=g.run_id;perform public.s2_log_event(g.run_id,room,null,'allocation_rework',null,jsonb_build_object('round_no',s.round_no,'resolution_source','group_allocation','behavior_scoring',false));result:=jsonb_build_object('ok',true,'allocation_valid',false);else update public.s6_run_state set allocation_valid=true,act_no=12,phase_key='act12_tasks',round_no=1,feedback_text_keys='{}',updated_at=now()where run_id=g.run_id;result:=jsonb_build_object('ok',true,'allocation_valid',true);end if;end if;insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'allocation',payload,result,now());return result;end$$;

create function public.s6_complete_station_guarded(p_room_code text,p_session_token text,p_client_request_id uuid,p_task_value text,p_expected_phase text,p_expected_step int,p_expected_round int)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;role text;task text;prior public.s6_action_receipts%rowtype;result jsonb;payload jsonb:=jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round,'value',p_task_value);begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'station_task'or prior.payload<>payload then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);if s.phase_key<>'act12_tasks'then raise exception'Station tasks are not open.';end if;select role_key into role from public.s6_allocations where run_id=g.run_id and player_id=p.player_id;if role='A'and p_task_value<>'1897'then raise exception'Incorrect municipal year.';elsif role='B'and p_task_value<>'lever_center' then raise exception'Lever has not reached center.';elsif role='C'and(p.role_slot<>'GAL-C'or p_task_value<>'silver_key_inserted'or not exists(select 1 from public.s3_player_items where run_id=g.run_id and physical_owner_id=p.player_id and item_key='linda_star_key'))then raise exception'Station C requires Linda physical ownership of the Silver Key.';elsif role='WATCHER'and p_task_value<>'corridor_watched'then raise exception'Watcher must watch the corridor.';end if;task:=case role when'A'then'year_1897'when'B'then'lever_center'when'C'then'silver_key_inserted'else'corridor_watched'end;insert into public.s6_station_tasks values(g.run_id,role,p.player_id,task,now());result:=jsonb_build_object('ok',true,'role_key',role,'task_key',task);insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'station_task',payload,result,now());return result;end$$;

create or replace function public.s6_engage(p_room_code text,p_session_token text,p_role_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;n int;failure text;begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into s from public.s6_run_state where run_id=g.run_id for update;if s.phase_key<>'act12_tasks'or not exists(select 1 from public.s6_allocations where run_id=g.run_id and player_id=p.player_id and role_key=p_role_key)or not exists(select 1 from public.s6_station_tasks where run_id=g.run_id and player_id=p.player_id and role_key=p_role_key)then raise exception'Role task must be completed before ENGAGE.';end if;insert into public.s6_engagements values(g.run_id,p_role_key,p.player_id,now())on conflict do nothing;select count(*)into n from public.s6_engagements where run_id=g.run_id;if n=3 then select role_key into failure from public.s6_allocations where run_id=g.run_id and role_key in('A','B','C')order by md5(g.run_id::text||role_key)limit 1;update public.s6_run_state set phase_key='act12_pressure',mechanism_failure_active=true,mechanism_failure_station=failure,failure_resolution='pending',round_no=1,feedback_text_keys=array[case failure when'A'then'act12.005'when'B'then'act12.006'else'act12.007'end],updated_at=now()where run_id=g.run_id;end if;return jsonb_build_object('ok',true,'engaged',n,'failure_started',n=3,'failure_station',case when n=3 then failure end);end$$;

create function public.s6_engage_guarded(p_room_code text,p_session_token text,p_client_request_id uuid,p_role_key text,p_expected_phase text,p_expected_step int,p_expected_round int)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;prior public.s6_action_receipts%rowtype;n int;failure text;result jsonb;payload jsonb:=jsonb_build_object('phase',p_expected_phase,'step',p_expected_step,'round',p_expected_round,'role',p_role_key);begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select*into prior from public.s6_action_receipts where run_id=g.run_id and player_id=p.player_id and request_id=p_client_request_id;if found then if prior.action_key<>'engage'or prior.payload<>payload then raise exception'Request identity reused with different content.';end if;return prior.result||jsonb_build_object('idempotent_replay',true);end if;select*into s from public.s6_run_state where run_id=g.run_id for update;perform public.s6_assert_identity(s,p_expected_phase,p_expected_step,p_expected_round);if s.phase_key<>'act12_tasks'or not exists(select 1 from public.s6_allocations where run_id=g.run_id and player_id=p.player_id and role_key=p_role_key)or not exists(select 1 from public.s6_station_tasks where run_id=g.run_id and player_id=p.player_id and role_key=p_role_key)then raise exception'Role task must be completed before ENGAGE.';end if;insert into public.s6_engagements values(g.run_id,p_role_key,p.player_id,now())on conflict do nothing;select count(*)into n from public.s6_engagements where run_id=g.run_id;if n=3 then select role_key into failure from public.s6_allocations where run_id=g.run_id and role_key in('A','B','C')order by md5(g.run_id::text||role_key)limit 1;update public.s6_run_state set phase_key='act12_pressure',mechanism_failure_active=true,mechanism_failure_station=failure,failure_resolution='pending',round_no=1,feedback_text_keys=array[case failure when'A'then'act12.005'when'B'then'act12.006'else'act12.007'end],updated_at=now()where run_id=g.run_id;end if;result:=jsonb_build_object('ok',true,'engaged',n,'failure_started',n=3,'failure_station',case when n=3 then failure end);insert into public.s6_action_receipts values(g.run_id,p.player_id,p_client_request_id,'engage',payload,result,now());return result;end$$;

create function public.s6_tick_cinematic(p_run uuid)returns void language plpgsql security definer set search_path=public as $$declare s public.s6_run_state%rowtype;nextstage int;keys text[];audio text;begin select*into s from public.s6_run_state where run_id=p_run for update;if s.phase_key<>'act12_cinematic'or s.stage_started_at+(case when s.cinematic_stage=8 then interval'2 seconds'else interval'1 second'end)>now()then return;end if;nextstage:=s.cinematic_stage+1;keys:=case nextstage when 2 then array['act12.017','act12.018','act12.019']when 3 then(case when s.gold_key then array['act12.020']else array['act12.018']end)when 4 then array['act12.021']when 5 then array['act12.022']when 6 then array['act12.023']when 7 then array['act12.024']when 8 then array['act12.025','act12.026']else array['act12.027']end;audio:=case nextstage when 2 then'audio.wet_scraping'when 3 then'audio.snakes_approaching'when 9 then'audio.mechanism_clang'when 10 then'audio.gate_opening'else null end;if nextstage>=10 then update public.s6_run_state set act_no=13,phase_key='act13_escape',cinematic_stage=10,stage_started_at=now(),failure_resolution='cinematic_auto_resolution',mechanism_failure_active=false,escape_success=true,feedback_text_keys=array['act12.027','act13.001','act13.002','act13.003'],feedback_audio_key='audio.gate_opening',updated_at=now()where run_id=p_run;perform public.s6_set_scene(p_run,'act13_escape','act13_escape','castle_exterior','CINEMATIC_MESSAGE','act13.001');else update public.s6_run_state set cinematic_stage=nextstage,stage_started_at=now(),feedback_text_keys=keys,feedback_audio_key=audio,updated_at=now()where run_id=p_run;end if;end$$;
revoke execute on function public.s6_tick_cinematic(uuid)from public,anon,authenticated;

create or replace function public.s6_get_player_state(p_room_code text,p_session_token text)returns jsonb language plpgsql security definer set search_path=public as $$declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s6_run_state%rowtype;d public.discussion_sessions%rowtype;begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);perform public.s6_tick_cinematic(g.run_id);select*into s from public.s6_run_state where run_id=g.run_id;if not found then return jsonb_build_object('active',false);end if;select*into d from public.discussion_sessions where run_id=g.run_id and status='discussion'order by vote_round desc limit 1;return jsonb_build_object('active',true,'state',to_jsonb(s),'role_slot',p.role_slot,'scene_asset_key',case when s.act_no=9 then'shared.great_hall'when s.act_no in(11,12)then'shared.main_gate'when s.act_no=13 then'ending.castle_exterior'end,'discussion',case when d.discussion_session_id is null then null else jsonb_build_object('discussion_session_id',d.discussion_session_id,'phase_key',d.phase_key,'step_key',d.step_key,'vote_round',d.vote_round,'phase_deadline',d.phase_deadline,'silent_texting_mode',d.silent_texting_mode,'messages',(select coalesce(jsonb_agg(jsonb_build_object('display_name',rp.display_name,'message_text',m.message_text,'created_at',m.created_at)order by m.message_id),'[]')from public.dialogue_messages m join public.s1_room_players rp using(player_id)where m.discussion_session_id=d.discussion_session_id))end,'private_clue',(select jsonb_build_object('knowledge_key',knowledge_key,'text_key',text_key)from public.s6_private_clues where run_id=g.run_id and player_id=p.player_id and act_no=s.act_no),'private_choices_revealed',case when s.act_no>10 or s.phase_key in('act10_discussion','act10_final_vote','act10_result')then(select coalesce(jsonb_agg(jsonb_build_object('role_slot',rp.role_slot,'choice_id',c.choice_id)order by rp.role_slot),'[]')from public.s6_choices c join public.s1_room_players rp using(player_id)where c.run_id=g.run_id and c.phase_key='act10_private')else'[]'::jsonb end,'allocation',(select role_key from public.s6_allocations where run_id=g.run_id and player_id=p.player_id),'station_task',(select task_key from public.s6_station_tasks where run_id=g.run_id and player_id=p.player_id),'engaged_roles',(select coalesce(jsonb_agg(role_key),'[]')from public.s6_engagements where run_id=g.run_id),'game_completed',false,'export_ready',false);end$$;

revoke execute on function public.s6_open_act9_console(text,text),public.s6_submit_group_choice(text,text,uuid,text),public.s6_submit_private_choice(text,text,uuid,text),public.s6_advance(text,text),public.s6_submit_allocation(text,text,uuid,text),public.s6_engage(text,text,text)from anon,authenticated;
grant execute on function public.s6_send_message_guarded(text,text,uuid,uuid,text),public.s6_close_discussion_guarded(text,text,text,int,int,uuid),public.s6_submit_group_choice_guarded(text,text,uuid,text,text,int,int),public.s6_submit_private_choice_guarded(text,text,uuid,text,text,int,int),public.s6_advance_guarded(text,text,uuid,text,int,int),public.s6_submit_allocation_guarded(text,text,uuid,text,text,int,int),public.s6_complete_station_guarded(text,text,uuid,text,text,int,int),public.s6_engage_guarded(text,text,uuid,text,text,int,int)to anon,authenticated;
commit;
